"""Migration of Meridian CRM 4.2 case_escalation.crms."""

from datetime import date


def _date_difference(today: str, open_date: object) -> int:
    """Return whole calendar days today - open_date under legacy semantics."""
    if not open_date or open_date == "00000000" or today == "00000000":
        return 0

    open_date_text = str(open_date)
    if len(today) != 8 or not today.isdigit():
        raise ValueError("today must be a YYYYMMDD date string")
    if len(open_date_text) != 8 or not open_date_text.isdigit():
        raise ValueError("OPEN_DT must be a YYYYMMDD date string or empty/sentinel")

    current = date(int(today[:4]), int(today[4:6]), int(today[6:8]))
    opened = date(
        int(open_date_text[:4]),
        int(open_date_text[4:6]),
        int(open_date_text[6:8]),
    )
    return (current - opened).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return workflow events for overdue live support cases in CASE_ID order."""
    events: list[dict] = []

    # CASE_MASTER is iterated by its primary key, CASE_ID, in ascending order.
    for case in sorted(cases, key=lambda row: row["CASE_ID"]):
        if case.get("DEL_FLG") == "Y":
            continue

        status = case.get("STAT_CD")
        age = _date_difference(today, case.get("OPEN_DT", ""))

        if status == "N" and age >= 2:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case["CASE_ID"]),
                    "event": "auto_escalate",
                }
            )
        elif status == "A" and case.get("ESC_FLG") != "Y" and age >= 7:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case["CASE_ID"]),
                    "event": "auto_escalate",
                }
            )

    return events
